import { BottomSheet, BottomSheetManager, BottomSheetRef, FormInput, GradientButton, IS_IOS, MaterialTextInput, MaterialTextInputPropsMethod, Spacer, Text, useTheme } from '@core/ui';
import React, { useEffect, useRef, useState } from 'react';
import useCSS from '@src/presentation/style';
import { Image, InputModeOptions, Keyboard, SafeAreaView, TextInput, TextInputProps, View } from 'react-native';
import { CURRENCY } from '@src/utils/constants';
import { ValidationResult } from '@src/utils/validator';
import { useTranslation } from '@core/service';
import { formatMoney } from '@src/utils/currency';
import getImg from '@src/utils/getImg';
import { CurrencyInput } from '../contentInputCurrency/currencyInput';

interface BottomSheetInputProps {
    label: string;
    onSubmit: (value: string) => void;
    labelSubmit: string;
    textInputProps: TextInputProps;
    show: boolean;
    title: string;
    onClose?: () => void;
    format?: string;
    inputType?: string;
    validate?: (value: string) => ValidationResult;
}

const BottomSheetInputCurrency = (props: BottomSheetInputProps) => {
    const { label, onSubmit, textInputProps, title, show, onClose, format, inputType, validate } = props;
    const { value, placeholder } = textInputProps;
    const bsRef = useRef<BottomSheetRef>(null);

    const handlePressSubmit = (value: string) => {
        onSubmit?.(value?.trim?.());
        bsRef.current?.close();
    };
    const onShowModal = () => {
        BottomSheetManager.show({
            render: (portalId) => (
                <BottomSheet ref={bsRef} id={portalId} title={title} description='' onClose={onClose} adjustKeyboard={false} safeAreaBottomOffset={IS_IOS ? 370 : undefined} snapPoints={['70%']} >
                    <ContentInput value={value ?? ''} onSubmit={handlePressSubmit} label={label} placeholder={placeholder} format={format} inputType={inputType} validate={validate} />
                </BottomSheet>
            ),
        });
    };

    useEffect(() => {
        if (show) {
            onShowModal();
        }
    }, [show]);

    return (
        <View></View>
    );
};

interface ContentInputProps {
    value: string;
    onSubmit: (text: string) => void;
    placeholder?: string;
    label?: string;
    inputType?: string;
    format?: string;
    validate?: (value: string) => ValidationResult;
    textInputProps?: TextInputProps;
}

interface ExtendTextInput extends TextInput, MaterialTextInputPropsMethod { }

const ContentInput = ({ value, onSubmit, placeholder, label, inputType = 'default', format, validate, textInputProps }: ContentInputProps) => {
    const css = useCSS();
    const { theme } = useTheme();
    const [displayValue, setDisplayValue] = useState(value);
    const [errorMessages, setErrorMessages] = useState<string>('');
    const { t } = useTranslation(['validator']);
    const [isFocus, setIsFocus] = useState(false);
    const [focus, setFocus] = useState(false);
    const inputRef = useRef<ExtendTextInput | null>(null);
    const handleInputWithFormat = (text: string) => {
        console.log('\x1b[31m pha__text', inputType, text);
        let value = text;
        if (inputType === 'numeric') {
            value = value.replace(/[^0-9]/g, '');
        }
        switch (format) {
            case 'money':
                value = formatMoney(text?.replace(/[^0-9]/g, '') ?? '');
                break;
            default:
                break;
        }
        setDisplayValue(value);
    };
    const handleValidate = (value: string) => {
        const validation = validate?.(value);
        if (validation?.isEmpty) {
            setErrorMessages(validation.errors || '');
            return false;
        }
        if (validation?.isInvalid) {
            setErrorMessages(validation?.errors || '');
            return false;
        }
        return true;
    };
    const handleSubmit = () => {
        const isValid = handleValidate(displayValue);
        if (!isValid) {
            return;
        }
        let submitValue = displayValue;
        switch (format) {
            case 'money':
                submitValue = displayValue?.replaceAll?.(',', '');
                break;
            default:
                break;
        }
        onSubmit?.(submitValue);
        Keyboard.dismiss();
    };
    useEffect(() => {
        // const isValid = handleValidate(displayValue);
        if (displayValue) {
            setErrorMessages('');
        }
        console.log('\x1b[31m displayValue', displayValue);
    }, [displayValue, focus]);
    useEffect(() => {
        setTimeout(() => {
            if (inputRef) {
                inputRef?.current?.focus();
            }
        }, 350);
    }, []);
    return (
        <SafeAreaView>
            <Spacer height={16} />
            <CurrencyInput
                ref={inputRef}
                label={label}
                placeholder={placeholder}
                // keyboardType={inputType}
                value={displayValue}
                onChangeText={handleInputWithFormat}
                autoFocus={false}
                inputMode={(inputType as InputModeOptions) || 'text'}
                {...textInputProps}
            />
            {/* <View style={[css.border_b_1, isFocus ? css.border_b_orange_600 : css.border_b_neutral_300]}>
                <View style={[css.row, css.justify_center, css.items_end]}>
                    <View style={[{ height: theme.Size.Vertical.ExtraLarge }, css.row, css.items_center]}>
                        <TextInput
                            keyboardType='number-pad'
                            autoFocus={isFocus}
                            value={displayValue}
                            onChangeText={handleInputWithFormat}
                            onFocus={() => setIsFocus(true)}
                            onBlur={() => setIsFocus(false)}
                            placeholder={'0'}
                            placeholderTextColor={theme.Colors.Border.Neutral400}
                            selectionColor={theme.Colors.Main.Orange}
                            style={[css.text_center, css.font_semibold, { ...theme.Typography.LargeTitle.Semibold }]}
                        />
                    </View>
                    <Text style={[css.ml_small, css.mb_medium, css.text_subheadline]}>{CURRENCY}</Text>
                </View>
            </View> */}
            <View style={[css.row, css.items_center, { gap: theme.Size.Horizontal.Base }]}>
                {errorMessages && <Image source={getImg('/assets/images/icons/icon_error_input.png')} style={{ width: theme.Size.Horizontal.Regular, height: theme.Size.Vertical.Regular }} />}
                <Text style={{ ...theme.Typography.TextCaption100.Regular, color: theme.Colors.Text.Error }}>{t(`${errorMessages}`)}</Text>
            </View>
            <Spacer height={56} />
            <GradientButton gradientProps={{ type: 'primary' }} title={t('btn_save')} onPress={handleSubmit} />
            <Spacer height={8} />
        </SafeAreaView>
    );
};

export default React.memo(BottomSheetInputCurrency);
